async function scanBundle(input, deliver) {
  const decoder = new TextDecoder("utf-8");
  const decodeBlockSize = 65536;

  let count = 0;
  let line = 1;
  let parts = [];

  async function deliverLine() {
    let text = parts.join("");
    parts = [];

    if (text.endsWith("\r")) {
      text = text.slice(0, -1);
    }

    if (text.trim().length === 0) {
      return false;
    }

    let value;
    try {
      value = JSON.parse(text);
    } catch (_) {
      const error = new Error(`Invalid JSON on line ${line}`);
      error.code = "BAD_LINE";
      error.line = line;
      throw error;
    }

    const result = await deliver(value, line);
    count += 1;
    return result === false;
  }

  async function consume(text) {
    let start = 0;

    for (;;) {
      const newline = text.indexOf("\n", start);
      if (newline === -1) {
        if (start < text.length) {
          parts.push(text.slice(start));
        }
        return false;
      }

      if (newline > start) {
        parts.push(text.slice(start, newline));
      }

      const stop = await deliverLine();
      line += 1;

      if (stop) {
        return true;
      }

      start = newline + 1;
    }
  }

  try {
    for (;;) {
      const chunk = await input.read();
      if (chunk === null) {
        break;
      }

      for (let offset = 0; offset < chunk.length; offset += decodeBlockSize) {
        const block = chunk.subarray(
          offset,
          Math.min(offset + decodeBlockSize, chunk.length)
        );
        const text = decoder.decode(block, { stream: true });

        if (await consume(text)) {
          return count;
        }
      }
    }

    const finalText = decoder.decode();
    if (await consume(finalText)) {
      return count;
    }

    if (parts.length !== 0) {
      await deliverLine();
    }

    return count;
  } finally {
    await input.close();
  }
}
